import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 1024}, num_warps=4, num_stages=2),
        triton.Config({"BLOCK_SIZE": 2048}, num_warps=4, num_stages=2),
    ],
    key=["N"],
)
@triton.jit
def exclusive_cumsum_kernel(
    x_ptr,
    out_ptr,
    M,
    N,
    stride_xm,
    stride_xn,
    stride_om,
    stride_on,
    BLOCK_SIZE: tl.constexpr,
):
    row_idx = tl.program_id(0)

    x_row_ptr = x_ptr + row_idx.to(tl.int64) * stride_xm
    o_row_ptr = out_ptr + row_idx.to(tl.int64) * stride_om

    running_sum = tl.zeros([1], dtype=tl.float32)

    for col_start in range(0, N, BLOCK_SIZE):
        col_offsets = col_start + tl.arange(0, BLOCK_SIZE)
        mask = col_offsets < N

        x = tl.load(x_row_ptr + col_offsets * stride_xn, mask=mask, other=0.0).to(
            tl.float32
        )

        inclusive = tl.cumsum(x, axis=0)
        exclusive = inclusive - x

        result = exclusive + running_sum

        tl.store(o_row_ptr + col_offsets * stride_on, result, mask=mask)

        running_sum += tl.sum(x, axis=0)


class Model(nn.Module):
    def __init__(self, dim):
        super(Model, self).__init__()
        self.dim = dim

    def forward(self, x):
        M, N = x.shape
        out = torch.empty_like(x)
        grid = (M,)
        exclusive_cumsum_kernel[grid](
            x,
            out,
            M,
            N,
            x.stride(0),
            x.stride(1),
            out.stride(0),
            out.stride(1),
        )
        return out
